<script setup lang="ts">
import {computed} from 'vue'
import {useRoute} from 'vue-router'
import {useAuthStore} from '../../stores/auth'
import {fetchWorkbench} from '../../api/workbench'
import {useBusinessRead} from '../../composables/useBusinessRead'
const auth=useAuthStore(),route=useRoute()
const canUse=computed(()=>auth.currentUser?.role!=='TECHNICIAN'||auth.currentUser.capabilities.canWorkOnTasks)
const {data,loading,message,stale,load}=useBusinessRead(()=>fetchWorkbench(),undefined,{target:()=>canUse.value?auth.currentUser?.id??null:null,poll:true})
const entries=computed(()=>!canUse.value?[]:auth.currentUser?.role==='REPORTER'?[{key:'needsSupplement',label:'待补充申请',path:'/requests?status=NEEDS_SUPPLEMENT'},{key:'pendingAcceptance',label:'待验收工单',path:'/work-orders?status=PENDING_ACCEPTANCE'},{key:'pendingReview',label:'申请待审核',path:'/requests?status=PENDING_REVIEW'}]:auth.currentUser?.role==='ADMIN'?[{key:'pendingReview',label:'待审核申请',path:'/admin/requests?status=PENDING_REVIEW'},{key:'reassignPending',label:'待重派工单',path:'/admin/work-orders?status=REASSIGN_PENDING'}]:[{key:'pendingAccept',label:'待接单',path:'/tasks?status=PENDING_ACCEPT'},{key:'inProgress',label:'普通处理中',path:'/tasks?status=IN_PROGRESS'},{key:'rework',label:'返工处理中',path:'/tasks?status=IN_PROGRESS'},{key:'pendingAcceptance',label:'已提交待验收',path:'/tasks?status=PENDING_ACCEPTANCE'}])
const names:Record<string,string>={PENDING_REVIEW:'待审核',NEEDS_SUPPLEMENT:'待补充',PENDING_ACCEPT:'待接单',REASSIGN_PENDING:'待重派',IN_PROGRESS:'处理中（含返工）',PENDING_ACCEPTANCE:'待验收'}
</script>
<template><div class="page-heading"><div><h1>{{canUse?'待办工作台':'资格与普通入口'}}</h1><p>当前权限下的真实待办，可通过普通列表完成业务。</p></div><button v-if="canUse" class="secondary" :disabled="loading" @click="load">刷新待办</button></div><p v-if="loading&&!data" role="status">正在读取待办数量…</p><p v-if="message" class="notice" role="alert">{{message}}{{stale?'；保留上次待办，数量已过期。':'；读取失败，数量未知。'}}</p><section v-if="!canUse" class="card"><p>通过资格审核后开放维修任务；当前可浏览校园并查看审核状态。</p><RouterLink to="/account/review">查看审核状态</RouterLink></section><div class="todo-grid"><RouterLink v-for="entry in entries" :key="entry.key" class="card" :to="entry.path"><h2>{{entry.label}}</h2><strong class="todo-number">{{data?.counts[entry.key]??'未知'}}</strong><p>{{entry.key==='rework'||entry.key==='inProgress'?'进入处理中列表，工单标有返工阶段':'进入对应普通列表'}}</p></RouterLink></div><section v-if="data" class="card"><h2>待办详情入口</h2><p>最多显示最早的20项；完整结果请使用上方列表。</p><p v-if="!data.items.length">当前没有待办。</p><ul class="business-list"><li v-for="item in data.items" :key="item.resourceType+item.id"><RouterLink :to="{path:item.resourceType==='WORK_ORDER'?`/work-orders/${item.id}`:auth.currentUser?.role==='ADMIN'?`/admin/requests/${item.id}`:`/requests/${item.id}`,query:{returnTo:route.fullPath}}">{{item.businessNo}} · {{item.equipmentName}} · {{names[item.status]??item.status}}</RouterLink></li></ul></section><section class="card"><h2>普通业务入口</h2><div class="actions"><RouterLink v-if="auth.currentUser?.capabilities.canCreateRequest" to="/requests/new">新建报修</RouterLink><RouterLink v-if="auth.currentUser?.role==='REPORTER'" to="/requests">我的申请</RouterLink><RouterLink v-if="auth.currentUser?.capabilities.canWorkOnTasks" to="/tasks">我的任务与历史</RouterLink><RouterLink v-if="auth.currentUser?.capabilities.canManage" to="/admin/requests">申请审核</RouterLink><RouterLink v-if="auth.currentUser?.capabilities.canManage" to="/equipment">设备台账</RouterLink><RouterLink v-if="auth.currentUser?.capabilities.canManage" to="/admin/personnel">人员管理</RouterLink><RouterLink to="/campus">校园总览</RouterLink><RouterLink to="/account/settings">账号设置</RouterLink></div></section></template>
<style scoped>.todo-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px}.todo-grid a{text-decoration:none;color:inherit}.todo-number{font-size:2rem}.card{margin-bottom:16px}.actions{flex-wrap:wrap}</style>

